def _filter_prefix_bytes(doc):
    """log-filter 末项摘要文本：前三键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in FILTER_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _filter_bytes(doc):
    """log-filter stdout 载荷：四键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in FILTER_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_filter(
    log_path, start_token, end_token, applied_token,
    max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false，否则 usage
    if _FILTER_BOUND_RE.fullmatch(start_token) is None:
        _fail("usage")
        return 2
    if _FILTER_BOUND_RE.fullmatch(end_token) is None:
        _fail("usage")
        return 2
    if applied_token not in ("*", "true", "false"):
        _fail("usage")
        return 2
    start = None if start_token == "*" else _limit_value(start_token)
    end = None if end_token == "*" else _limit_value(end_token)
    if start is not None and end is not None and start > end:
        _fail("usage")
        return 2
    want_applied = None if applied_token == "*" else (applied_token == "true")
    try:
        with open(log_path, "rb") as handle:
            # 分块至多 65536 字节读取，输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 仅静态校验：顶层/记录键序与字段类型、config/event 规范键序、
        # event 已知键形、内部 sha256；不校验配置语义、不重演事件，
        # 也不推导 version/applied/output
        log = parse_json(log_raw)
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        kept = []
        for record in log["records"]:
            if start is not None and record["t"] < start:
                continue
            if end is not None and record["t"] > end:
                continue
            if want_applied is not None and record["applied"] is not want_applied:
                continue
            kept.append(record)
        # 原样记录（同对象）保留原序；schema 固定 1，source_sha256 取原摘要
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": log["sha256"],
            "records": kept,
        }
        doc["sha256"] = hashlib.sha256(_filter_prefix_bytes(doc)).hexdigest()
        payload = _filter_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


SUMMARY_DIGEST_KEYS = ("schema", "source_sha256", "total", "applied", "kinds")
# kinds 固定全列此序，缺类补 0；kind 仅取静态事件键形，不重演推导
SUMMARY_KINDS = (
    "learn", "frame", "link", "member", "service", "reload", "rollback",
)


def _summary_prefix_bytes(doc):
    """log-summary 末项摘要文本：前五键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in SUMMARY_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _summary_bytes(doc):
    """log-summary stdout 载荷：六键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in SUMMARY_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_summary(log_path, max_log_bytes, max_output_bytes):
    try:
        with open(log_path, "rb") as handle:
            # 读取与字节边界完全沿用 log-filter：分块至多 65536 字节，
            # 输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 与 log-filter 同一套静态校验：顶层/记录键序与字段类型、
        # config/event 规范键序、event 已知键形、内部 sha256；不重演、
        # 不推导 version/applied/output，applied 直接取记录字段
        log = parse_json(log_raw)
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        totals = {kind: 0 for kind in SUMMARY_KINDS}
        applied_counts = {kind: 0 for kind in SUMMARY_KINDS}
        total = 0
        applied_total = 0
        for record in log["records"]:
            kind = _event_kind(record["event"])
            totals[kind] += 1
            total += 1
            if record["applied"]:
                applied_counts[kind] += 1
                applied_total += 1
        # kinds 按固定序全列，项键序 kind,total,applied，缺类补 0
        kinds = [
            {
                "kind": kind,
                "total": totals[kind],
                "applied": applied_counts[kind],
            }
            for kind in SUMMARY_KINDS
        ]
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": log["sha256"],
            "total": total,
            "applied": applied_total,
            "kinds": kinds,
        }
        doc["sha256"] = hashlib.sha256(_summary_prefix_bytes(doc)).hexdigest()
        payload = _summary_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


PAGE_DIGEST_KEYS = ("schema", "source_sha256", "records", "next")
# log-page 的 CURSOR：* 或 <sha256>:<offset>，sha256 为 64 位小写十六进制，
# offset 为 0 或无前导零正整数（任意长度）
_PAGE_CURSOR_RE = re.compile(r"\*|[0-9a-f]{64}:(?:0|[1-9][0-9]*)")


def _page_prefix_bytes(doc):
    """log-page 末项摘要文本：前四键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in PAGE_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _page_bytes(doc):
    """log-page stdout 载荷：五键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in PAGE_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_page(
    log_path, cursor_token, count_token,
    max_log_bytes, max_output_bytes,
):
    # CURSOR 为 * 或 <sha256>:<offset>；COUNT 为不限长正十进制；
    # 格式非法按 usage 退出 2（在打开文件之前判定）
    if _PAGE_CURSOR_RE.fullmatch(cursor_token) is None:
        _fail("usage")
        return 2
    if _LIMIT_RE.fullmatch(count_token) is None:
        _fail("usage")
        return 2
    count = _limit_value(count_token)
    try:
        with open(log_path, "rb") as handle:
            # 读取与字节边界完全沿用 log-filter：分块至多 65536 字节，
            # 输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 与 log-filter 同一套静态校验与内部摘要核对：顶层/记录键序与
        # 字段类型、config/event 规范键序、event 已知键形、内部 sha256；
        # 不校验配置语义、不重演事件
        log = parse_json(log_raw)
        _validate_log_shape(log)
        source_sha = log["sha256"]
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != source_sha:
            raise InvalidInput("bad log sha256")
        records = log["records"]
        total = len(records)
        if cursor_token == "*":
            # * 从 records 下标 0 开始
            offset = 0
        else:
            cursor_sha, offset_token = cursor_token.split(":", 1)
            # 其他游标的摘要须等于 LOG.sha256 且 offset≤记录数
            if cursor_sha != source_sha:
                raise InvalidInput("bad cursor sha256")
            offset = _limit_value(offset_token)
            if offset > total:
                raise InvalidInput("bad cursor offset")
        # 从 offset 按原序取至多 COUNT 条原样记录（同对象）
        page = records[offset:offset + count]
        next_index = offset + len(page)
        # 有后续时 next 为 LOG.sha256:<下一下标>，否则 null
        nxt = (
            source_sha + ":" + str(next_index)
            if next_index < total
            else None
        )
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": source_sha,
            "records": page,
            "next": nxt,
        }
        doc["sha256"] = hashlib.sha256(_page_prefix_bytes(doc)).hexdigest()
        payload = _page_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


QUERY_DIGEST_KEYS = ("schema", "source_sha256", "query", "records", "next")
QUERY_QUERY_KEYS = ("start", "end", "kind", "applied")
# log-query 的 KIND：*（任意）或 learn/frame/link/member/service/reload/
# rollback（与 log-summary 同口径，仅取静态事件键形，不重演推导）
_QUERY_KINDS = frozenset(
    ("learn", "frame", "link", "member", "service", "reload", "rollback")
)


def _query_prefix_bytes(doc):
    """log-query 末项摘要文本：前五键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in QUERY_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _query_bytes(doc):
    """log-query stdout 载荷：六键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in QUERY_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_query(
    log_path, start_token, end_token, kind_token, applied_token,
    cursor_token, count_token, max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false；KIND 取 * 或已知七类；
    # CURSOR/COUNT 完全沿用 log-page；格式非法按 usage 退出 2（打开文件前）
    if _FILTER_BOUND_RE.fullmatch(start_token) is None:
        _fail("usage")
        return 2
    if _FILTER_BOUND_RE.fullmatch(end_token) is None:
        _fail("usage")
        return 2
    if kind_token != "*" and kind_token not in _QUERY_KINDS:
        _fail("usage")
        return 2
    if applied_token not in ("*", "true", "false"):
        _fail("usage")
        return 2
    if _PAGE_CURSOR_RE.fullmatch(cursor_token) is None:
        _fail("usage")
        return 2
    if _LIMIT_RE.fullmatch(count_token) is None:
        _fail("usage")
        return 2
    start = None if start_token == "*" else _limit_value(start_token)
    end = None if end_token == "*" else _limit_value(end_token)
    if start is not None and end is not None and start > end:
        _fail("usage")
        return 2
    want_applied = None if applied_token == "*" else (applied_token == "true")
    want_kind = None if kind_token == "*" else kind_token
    count = _limit_value(count_token)
    try:
        with open(log_path, "rb") as handle:
            # 读取与字节边界完全沿用 log-filter：分块至多 65536 字节，
            # 输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 与 log-page 同一套静态校验与内部摘要核对：顶层/记录键序与
        # 字段类型、config/event 规范键序、event 已知键形、内部 sha256；
        # 不校验配置语义、不重演事件
        log = parse_json(log_raw)
        _validate_log_shape(log)
        source_sha = log["sha256"]
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != source_sha:
            raise InvalidInput("bad log sha256")
        records = log["records"]
        total = len(records)
        if cursor_token == "*":
            # * 从原 LOG records 下标 0 开始
            offset = 0
        else:
            cursor_sha, offset_token = cursor_token.split(":", 1)
            # 游标摘要须等于 LOG.sha256 且 offset≤记录数（沿用 log-page）
            if cursor_sha != source_sha:
                raise InvalidInput("bad cursor sha256")
            offset = _limit_value(offset_token)
            if offset > total:
                raise InvalidInput("bad cursor offset")
        # 从 offset 起扫描，时间闭区间、kind、applied 合取，原序原样取
        # 至多 COUNT 项；matched 记 (原始下标, 原样记录)
        matched = []
        i = offset
        while i < total and len(matched) < count:
            record = records[i]
            if start is None or record["t"] >= start:
                if end is None or record["t"] <= end:
                    if want_kind is None or _event_kind(
                        record["event"]
                    ) == want_kind:
                        if want_applied is None or record[
                            "applied"
                        ] is want_applied:
                            matched.append((i, record))
            i += 1
        # 已收满 COUNT 项且其后仍有匹配项时 next 为 LOG.sha256:<最后返回
        # 项的下一原始下标>（最后匹配项下标 +1）；否则 null。向前只判定
        # 是否仍有匹配，游标本身指最后返回项的紧后原始下标（同 log-page
        # 的“下一下标”，命名空间为原 LOG records 下标）
        nxt = None
        if len(matched) == count:
            last_index = matched[-1][0]
            j = last_index + 1
            while j < total:
                candidate = records[j]
                if (
                    (start is None or candidate["t"] >= start)
                    and (end is None or candidate["t"] <= end)
                    and (
                        want_kind is None
                        or _event_kind(candidate["event"]) == want_kind
                    )
                    and (
                        want_applied is None

                        or candidate["applied"] is want_applied
                    )
                ):
                    nxt = source_sha + ":" + str(last_index + 1)
                    break
                j += 1
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": source_sha,
            # query 固定四键序：输入 * 写 null，其余整数、整数、字符串、布尔
            "query": {
                "start": start,
                "end": end,
                "kind": want_kind,
                "applied": want_applied,
            },
            "records": [record for _, record in matched],
            "next": nxt,
        }
        doc["sha256"] = hashlib.sha256(_query_prefix_bytes(doc)).hexdigest()
        payload = _query_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
        cost = 1 + len(value)
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(value):
            remaining = _diff_size_charge(value[key], remaining)
        return remaining
    if isinstance(value, list):
        if remaining < 1:
            raise DiffWorkLimit
        remaining -= 1
        for item in value:
            remaining = _diff_size_charge(item, remaining)
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    return remaining - 1


def _diff_work(old, new, remaining):
    """按工作量公式无副作用预演 D，返回剩余额度（耗尽为 0）。

    两值均为对象时计 1+并集键数，共有键递归计 D，单侧键计该侧 S；
    其余（含数组整体）计 1+S(旧值)+S(新值)。键按 Unicode 码点升序
    累计，递归逐层传递剩余额度；等于上限合法，首次超过即抛
    DiffWorkLimit，此后不再访问后续元素、键值或单侧子树。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        cost = 1 + len(set(old) | set(new))
        if cost > remaining:
            raise DiffWorkLimit
        remaining -= cost
        for key in sorted(set(old) | set(new)):
            if key in old and key in new:
                remaining = _diff_work(old[key], new[key], remaining)
            else:
                remaining = _diff_size_charge(
                    old[key] if key in old else new[key], remaining
                )
        return remaining
    if remaining < 1:
        raise DiffWorkLimit
    remaining -= 1
    remaining = _diff_size_charge(old, remaining)
    return _diff_size_charge(new, remaining)


def _cmd_config_diff(
    old_path,
    new_path,
    max_diff_work=DEFAULT_MAX_DIFF_WORK,
    max_input_bytes=CONFIG_DIFF_MAX_INPUT_BYTES,
    max_output_bytes=None,
):
    if max_output_bytes is None:
        # 调用时解析缺省：测试可在导入后补丁 DEFAULT_MAX_OUTPUT_BYTES
        max_output_bytes = DEFAULT_MAX_OUTPUT_BYTES
    try:
        # 先打开两文件，任一失败即停；均可读后按 OLD、NEW 顺序分块读
        with open(old_path, "rb") as old_handle, open(
            new_path, "rb"
        ) as new_handle:
            old_raw = _read_limited(old_handle, max_input_bytes)
            if old_raw is None:
                _fail("input_limit")
                return 5
            new_raw = _read_limited(new_handle, max_input_bytes)
            if new_raw is None:
                _fail("input_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        old_config = parse_json(old_raw)
        new_config = parse_json(new_raw)
        # 两份均按既有 port-security 契约全量解析校验
        validate_security_config(old_config)
        validate_security_config(new_config)
        # 语义校验后先无副作用预演根值 D；首次超过即停止，不生成差异
        _diff_work(old_config, new_config, max_diff_work)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except DiffWorkLimit:
        _fail("diff_work_limit")
        return 5
    changes = []
